  # @absltest.skip("test a single experiment")
  def test_ckks_context_encode_decode(self):
    # Paramters Setup
    params = self.params.copy()
    params.update({
      "output_scale": self.scaling_factor,
    })
    # Initialization
    ctx = ckks_ctx.CKKSContext(params)
    # Step 1: Encoding
    encoded_ct1 = ctx.encode(self.real_values_input_in1)
    encoded_ct2 = ctx.encode(self.real_values_input_in2)
    np.testing.assert_array_equal(encoded_ct1.polynomial[0], self.ptxt1)
    np.testing.assert_array_equal(encoded_ct2.polynomial[0], self.ptxt2)

    # Step 2: Decoding
    decoded_values1 = ctx.decode(encoded_ct1, is_ntt=True)
    decoded_values2 = ctx.decode(encoded_ct2, is_ntt=True)
    np.testing.assert_array_almost_equal(decoded_values1, self.real_values_input_in1, decimal=3)
    np.testing.assert_array_almost_equal(decoded_values2, self.real_values_input_in2, decimal=3)

