    ek = kg.gen_evaluation_key(secret_key, q=self.q_towers, P=self.p_towers, noise_std=self.sigma, noise_scale=1, dnum=dnum)
    eval_key_a, eval_key_b = jnp.array(ek["a"], dtype=jnp.uint32).transpose(0,2,1), jnp.array(ek["b"], dtype=jnp.uint32).transpose(0,2,1)
    params = self.params.copy()
    params.update({
        "secret_key": secret_key,
        "public_key": public_key,
        "evaluation_key": [eval_key_a, eval_key_b],
    })

    # Initialization
    ctx = ckks_ctx.CKKSContext(params)
    he_mul = HEMul(batch, r, c, dnum, num_eval_mult, self.q_towers, self.p_towers, composite_degree=composite_degree)
    he_mul.control_gen(degree_layout=self.degree_layout, composite_degree=composite_degree, skip_rescale=True)
    he_mul.setup_relinearization(eval_key_a, eval_key_b)
    # Step 1: Encoding
    encoded_ct1 = ctx.encode(self.real_values_input_in1)
    encoded_ct2 = ctx.encode(self.real_values_input_in2)
    np.testing.assert_array_equal(encoded_ct1.polynomial[0], self.ptxt1)
    np.testing.assert_array_equal(encoded_ct2.polynomial[0], self.ptxt2)

    # Step 2: Encryption
    encrypted_ct1 = ctx.encrypt(encoded_ct1, v=self.v1, e=self.e1)
    encrypted_ct2 = ctx.encrypt(encoded_ct2, v=self.v2, e=self.e2)
    np.testing.assert_array_equal(encrypted_ct1.polynomial[0], self.ct1)
    np.testing.assert_array_equal(encrypted_ct2.polynomial[0], self.ct2)

    # Step 3: Homomorphic Multiplication
    in_cts_array = jnp.concatenate([encrypted_ct1.polynomial, encrypted_ct2.polynomial], axis=1).reshape(batch, 2*num_elements, r, c, len(self.q_towers)).astype(jnp.uint32)
    ct_in_shapes = {'batch': batch, 'num_elements': 2*num_elements, 'degree': self.degree, 'precision': 32, 'num_moduli': len(self.q_towers), 'degree_layout': (r, c)}
    ct_in = Polynomial(ct_in_shapes, parameters={'moduli': self.q_towers})
    ct_in.polynomial = in_cts_array
    encrypted_result = he_mul.mul(ct_in)
    # Step 4: Decryption - create fresh Polynomial with correct moduli (as in hemul_double_rescaling_test.py)
    ct_result_shapes = {'batch': batch, 'num_elements': num_elements, 'degree': self.degree,
                        'precision': 32, 'num_moduli': len(self.q_towers), 'degree_layout': (self.degree, )}
    ct_result_params = {'finite_field_context': ff_context.BarrettContext, 'r': r, 'c': c,
                        'moduli': self.q_towers}
    ct_result = Polynomial(ct_result_shapes, ct_result_params)
    ct_result.set_batch_polynomial(encrypted_result.polynomial.reshape(batch, num_elements, self.degree, len(self.q_towers)))
    decrypted_result = ctx.decrypt(ct_result)
    # Step 5: Decoding
    decoded_values = ctx.decode(decrypted_result, is_ntt=False)
    np.testing.assert_array_almost_equal(decoded_values, self.real_values_multiply_result, decimal=3)

